-- Compares every row of every table between the OLD database and the NEW one.
-- 1. Find & Replace __OLD__ and __NEW__ with the two database names.  2. Run in phpMyAdmin (SQL tab).
-- Result: one line per table. Rows that were moved by quarantine_orphans.sql show up in archived_rows.
-- Every line must show identical = 1  (old rows == kept + archived, and the content hash matches).

USE `__NEW__`;
DROP TEMPORARY TABLE IF EXISTS verify_result;
CREATE TEMPORARY TABLE verify_result (tbl VARCHAR(80), old_rows INT, kept_rows INT, archived_rows INT, identical TINYINT);

-- audit_log
SET @an = 0, @ah = 0;
SET @s = IF((SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = '__NEW__' AND table_name = 'archive_audit_log') > 0, 'SELECT COUNT(*), COALESCE(SUM(CRC32(CONCAT_WS(''|'', COALESCE(CAST(`id` AS CHAR),''<NULL>''), COALESCE(CAST(`submission_id` AS CHAR),''<NULL>''), COALESCE(CAST(`action` AS CHAR),''<NULL>''), COALESCE(CAST(`actor` AS CHAR),''<NULL>''), COALESCE(CAST(`notes` AS CHAR),''<NULL>''), COALESCE(CAST(`created_at` AS CHAR),''<NULL>'')))),0) INTO @an, @ah FROM `__NEW__`.`archive_audit_log`', 'DO 0');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
INSERT INTO verify_result SELECT 'audit_log', o.n, w.n, @an, (o.n = w.n + @an AND o.h = w.h + @ah) FROM (SELECT COUNT(*) AS n, COALESCE(SUM(CRC32(CONCAT_WS('|', COALESCE(CAST(`id` AS CHAR),'<NULL>'), COALESCE(CAST(`submission_id` AS CHAR),'<NULL>'), COALESCE(CAST(`action` AS CHAR),'<NULL>'), COALESCE(CAST(`actor` AS CHAR),'<NULL>'), COALESCE(CAST(`notes` AS CHAR),'<NULL>'), COALESCE(CAST(`created_at` AS CHAR),'<NULL>')))),0) AS h FROM `__OLD__`.`audit_log`) o, (SELECT COUNT(*) AS n, COALESCE(SUM(CRC32(CONCAT_WS('|', COALESCE(CAST(`id` AS CHAR),'<NULL>'), COALESCE(CAST(`submission_id` AS CHAR),'<NULL>'), COALESCE(CAST(`action` AS CHAR),'<NULL>'), COALESCE(CAST(`actor` AS CHAR),'<NULL>'), COALESCE(CAST(`notes` AS CHAR),'<NULL>'), COALESCE(CAST(`created_at` AS CHAR),'<NULL>')))),0) AS h FROM `__NEW__`.`audit_log`) w;
