SET @s = IF((SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = '__NEW__' AND table_name = 'archive_tracker_drafts') > 0, 'SELECT COUNT(*), COALESCE(SUM(CRC32(CONCAT_WS(''|'', COALESCE(CAST(`id` AS CHAR),''<NULL>''), COALESCE(CAST(`client_id` AS CHAR),''<NULL>''), COALESCE(CAST(`entity` AS CHAR),''<NULL>''), COALESCE(CAST(`fiscal_year` AS CHAR),''<NULL>''), COALESCE(CAST(`asset_id` AS CHAR),''<NULL>''), COALESCE(CAST(`period` AS CHAR),''<NULL>''), COALESCE(CAST(`value` AS CHAR),''<NULL>''), COALESCE(CAST(`edited_by` AS CHAR),''<NULL>''), COALESCE(CAST(`updated_at` AS CHAR),''<NULL>'')))),0) INTO @an, @ah FROM `__NEW__`.`archive_tracker_drafts`', 'DO 0');
