INSERT INTO verify_result SELECT 'tracker_drafts', o.n, w.n, @an, (o.n = w.n + @an AND o.h = w.h + @ah) FROM (SELECT COUNT(*) AS n, COALESCE(SUM(CRC32(CONCAT_WS('|', COALESCE(CAST(`id` AS CHAR),'<NULL>'), COALESCE(CAST(`client_id` AS CHAR),'<NULL>'), COALESCE(CAST(`entity` AS CHAR),'<NULL>'), COALESCE(CAST(`fiscal_year` AS CHAR),'<NULL>'), COALESCE(CAST(`asset_id` AS CHAR),'<NULL>'), COALESCE(CAST(`period` AS CHAR),'<NULL>'), COALESCE(CAST(`value` AS CHAR),'<NULL>'), COALESCE(CAST(`edited_by` AS CHAR),'<NULL>'), COALESCE(CAST(`updated_at` AS CHAR),'<NULL>')))),0) AS h FROM `__OLD__`.`tracker_drafts`) o, (SELECT COUNT(*) AS n, COALESCE(SUM(CRC32(CONCAT_WS('|', COALESCE(CAST(`id` AS CHAR),'<NULL>'), COALESCE(CAST(`client_id` AS CHAR),'<NULL>'), COALESCE(CAST(`entity` AS CHAR),'<NULL>'), COALESCE(CAST(`fiscal_year` AS CHAR),'<NULL>'), COALESCE(CAST(`asset_id` AS CHAR),'<NULL>'), COALESCE(CAST(`period` AS CHAR),'<NULL>'), COALESCE(CAST(`value` AS CHAR),'<NULL>'), COALESCE(CAST(`edited_by` AS CHAR),'<NULL>'), COALESCE(CAST(`updated_at` AS CHAR),'<NULL>')))),0) AS h FROM `__NEW__`.`tracker_drafts`) w;
